    schedule: [{ day: "Monday", plan: "Session A", purpose: "Hinge and press" }, { day: "Wednesday", plan: "Session B", purpose: "Squat and pull" }, { day: "Friday", plan: "Session C", purpose: "Single-leg and carries" }, { day: "Other days", plan: "Rest or walking", purpose: "Recover" }],
    warmupIntro: "One easy round, then a few light swings before the working sets. Hinging cold is the most common way people hurt their back with a bell.", warmup: sharedWarmup,
