    alternatives: [alt("Kettlebell Swing", "Kettlebell Deadlift", "You are still learning the hinge or the bell is too heavy to control."), alt("Kettlebell Turkish Get-Up", "Half-Kneeling Press", "The full get-up is beyond you right now."), alt("Kettlebell High Pull", "Kettlebell Row", "The shoulder does not like the high pull position."), alt("Bulgarian Split Squat", "Reverse Lunge", "You have nothing suitable to elevate the rear foot on.")],
