    sessions: [
      { name: "Volume cut (default)", intro: "Best for general accumulated fatigue. Keep loads, halve the sets.", exercises: [r("Barbell Back Squat", "2", "5 reps", "3 min", "Same load as your last good week, half the sets."), r("Dumbbell Bench Press", "2", "6-8 reps", "2 min", "Stop well short of failure."), r("Seated Cable Row", "2", "8-10 reps", "90 sec", "Comfortable and controlled."), r("Romanian Deadlift", "2", "6 reps", "2 min", "Keep it easy; this is not a test week."), r("Plank", "2", "30 sec", "60 sec", "Unchanged.")] },
      { name: "Intensity cut", intro: "Best when joints ache rather than when you feel systemically tired. Keep sets, drop load.", exercises: [r("Barbell Back Squat", "3", "5 reps", "2 min", "Roughly two thirds of your usual load."), r("Dumbbell Bench Press", "3", "8 reps", "90 sec", "Lighter, full range, no strain."), r("Lat Pulldown", "3", "10 reps", "90 sec", "Comfortable throughout."), r("Leg Press", "3", "10 reps", "2 min", "Easier on the joints than a loaded bar."), r("Dead Bug", "2", "8 each side", "60 sec", "Unchanged.")] },
      { name: "Frequency cut", intro: "Best when life is the problem rather than training. Train less often, keep sessions normal.", exercises: [r("Barbell Back Squat", "3", "5 reps", "3 min", "Normal session, run twice this week instead of four times."), r("Overhead Press", "3", "6-8 reps", "2 min", "Normal."), r("Pull-Up", "3", "6 reps", "2 min", "Normal."), r("Barbell Hip Thrust", "3", "8 reps", "2 min", "Normal."), r("Side Plank", "2", "30 sec each side", "60 sec", "Normal.")] },
    ],
    alternatives: [alt("Barbell Back Squat", "Goblet Squat", "You want to reduce spinal loading during the deload."), alt("Pull-Up", "Lat Pulldown", "Bodyweight pulling is part of what is beaten up."), alt("Romanian Deadlift", "Leg Curl", "The low back is the tissue that needs the break."), alt("Overhead Press", "Dumbbell Shoulder Press", "The shoulder is what needs unloading.")],
    progressionIntro: "The deload only pays off if you change something when you return. Repeating the block that caused the stall usually reproduces the stall.",
    progression: ["Return at the loads you held during the deload, not at the loads from your best week before it.", "If the stall came from too much volume, come back with one fewer set per exercise than before.", "If it came from grinding every set, come back leaving two or three reps in reserve.", "One deload week is almost always enough. Two in a row usually means the problem is sleep, food, or life stress rather than training."],
    recovery: ["Expect to feel worse for the first two or three days of a deload. Fatigue clearing is not immediate.", "Do not replace lifting volume with extra conditioning; that defeats the purpose entirely.", "Sleep is the variable that makes a deload work. A deload week with poor sleep achieves very little."],
    faq: [{ question: "How often do I need a deload?", answer: "Roughly every six to eight weeks of genuinely hard training, or whenever performance drops across two consecutive weeks. Less frequent training rarely needs them at all." }, { question: "Will I lose strength during a deload?", answer: "No. A week at reduced volume maintains strength easily, and most people come back stronger because the fatigue masking their fitness has cleared." }, { question: "Should I deload if I feel fine?", answer: "If performance is still climbing and nothing hurts, keep training. Deloads solve a problem; they are not a reward." }],
    safety: "Stop if an exercise produces sharp pain, dizziness, or chest pain. Persistent fatigue that a deload does not resolve deserves a medical conversation rather than another training adjustment.",
    sourceIds: ["acsm2002", "acsm2026", "volume"], related: ["how-to-break-a-strength-plateau", "progressive-overload-guide", "training-on-poor-sleep"],
    cta: { title: "Deload when the data says so", body: "DoThis watches your completed sets across weeks and pulls volume back before a stall turns into a lost month.", label: "Try DoThis" },
